import React, { useState, useEffect } from 'react';
import axios from 'axios';
import ClienteList from './components/ClienteList';
import CreateCliente from './components/CreateCliente';

const App = () => {
  const [clientes, setClientes] = useState([]);

  // Carrega a lista inicial de clientes quando o componente é montado
  useEffect(() => {
    axios.get('/clientes')
      .then(response => {
        setClientes(response.data); // Atualiza a lista de clientes
      })
      .catch(error => {
        console.error('Erro ao carregar os clientes:', error);
      });
  }, []);

  // Função que será passada para o componente CreateCliente
  const handleCreateCliente = (cliente) => {
    setClientes([...clientes, cliente]); // Adiciona o novo cliente à lista local
  };

  return (
    <div>
      <h1>Gestão de Clientes</h1>
      <CreateCliente onCreate={handleCreateCliente} />
      <ClienteList clientes={clientes} />
    </div>
  );
};

export default App;
